  1→"""
  2→Synapse Design System — Qt Stylesheet Generator
  3→
  4→Generates QSS (Qt Style Sheets) from design tokens for the Synapse panel.
  5→Houdini uses PySide2/Qt5 — all styles target that environment.
  6→
  7→Usage:
  8→    from synapse_styles import generate_stylesheet, STATUS_STYLES
  9→    widget.setStyleSheet(generate_stylesheet())
 10→"""
 11→
 12→import sys
 13→import os
 14→
 15→# Allow importing tokens from the design directory
 16→_design_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)))
 17→if _design_dir not in sys.path:
 18→    sys.path.insert(0, _design_dir)
 19→
 20→from tokens import (
 21→    SIGNAL, VOID, NEAR_BLACK, CARBON, GRAPHITE, SLATE, SILVER, BONE, WHITE,
 22→    FIRE, GROW, WARN, ERROR,
 23→    FONT_MONO, FONT_MONO_FALLBACKS, FONT_SANS, FONT_SANS_FALLBACKS,
 24→    SIZE_LABEL, SIZE_SMALL, SIZE_UI, SIZE_BODY, SIZE_TITLE, SIZE_HERO,
 25→    SPACE_XS, SPACE_SM, SPACE_MD, SPACE_LG,
 26→    STATES,
 27→)
 28→
 29→
 30→def _font_family(primary, fallbacks):
 31→    """Build a CSS font-family string."""
 32→    fonts = [primary] + list(fallbacks)
 33→    return ", ".join(f'"{f}"' for f in fonts)
 34→
 35→
 36→MONO_FAMILY = _font_family(FONT_MONO, FONT_MONO_FALLBACKS)
 37→SANS_FAMILY = _font_family(FONT_SANS, FONT_SANS_FALLBACKS)
 38→
 39→
 40→def generate_stylesheet():
 41→    """Generate the full QSS stylesheet for the Synapse panel."""
 42→    return f"""
 43→/* ═══════════════════════════════════════════════════════
 44→   SYNAPSE DESIGN SYSTEM — Qt Stylesheet
 45→   Generated from design tokens. Do not edit directly.
 46→   ═══════════════════════════════════════════════════════ */
 47→
 48→/* ── Base Panel ──────────────────────────────────────── */
 49→
 50→QWidget#synapse_panel {{
 51→    background-color: {NEAR_BLACK};
 52→    color: {BONE};
 53→    font-family: {SANS_FAMILY};
 54→    font-size: {SIZE_BODY}px;
 55→}}
 56→
 57→/* ── Unified Header ──────────────────────────────────── */
 58→
 59→QWidget#panel_header {{
 60→    background-color: {VOID};
 61→    border-bottom: 1px solid {GRAPHITE};
 62→    min-height: 36px;
 63→    max-height: 36px;
 64→}}
 65→
 66→QLabel#title_label {{
 67→    color: {WHITE};
 68→    font-family: {MONO_FAMILY};
 69→    font-size: {SIZE_TITLE}px;
 70→    font-weight: 600;
 71→    letter-spacing: 2px;
 72→}}
 73→
 74→QLabel#status_dot {{
 75→    font-size: 8px;
 76→    min-width: 8px;
 77→    max-width: 8px;
 78→}}
 79→
 80→QLabel#status_label {{
 81→    color: {SILVER};
 82→    font-family: {MONO_FAMILY};
 83→    font-size: {SIZE_SMALL}px;
 84→    letter-spacing: 1px;
 85→}}
 86→
 87→QLabel#status_detail {{
 88→    color: {SLATE};
 89→    font-family: {MONO_FAMILY};
 90→    font-size: {SIZE_LABEL}px;
 91→}}
 92→
 93→QToolButton#overflow_button {{
 94→    background-color: transparent;
 95→    color: {SILVER};
 96→    border: none;
 97→    font-family: {MONO_FAMILY};
 98→    font-size: {SIZE_UI}px;
 99→    padding: 2px {SPACE_SM}px;
100→    min-width: 28px;
101→}}
102→
103→QToolButton#overflow_button:hover {{
104→    color: {WHITE};
105→    background-color: {GRAPHITE};
106→    border-radius: 3px;
107→}}
108→
109→QToolButton#overflow_button::menu-indicator {{
110→    image: none;
111→}}
112→
113→/* ── Overflow Menu ───────────────────────────────────── */
114→
115→QMenu#overflow_menu {{
116→    background-color: {CARBON};
117→    color: {BONE};
118→    border: 1px solid {GRAPHITE};
119→    border-radius: 4px;
120→    font-family: {MONO_FAMILY};
121→    font-size: {SIZE_SMALL}px;
122→    padding: {SPACE_XS}px 0px;
123→}}
124→
125→QMenu#overflow_menu::item {{
126→    padding: {SPACE_SM}px {SPACE_MD}px;
127→}}
128→
129→QMenu#overflow_menu::item:selected {{
130→    background-color: {GRAPHITE};
131→    color: {SIGNAL};
132→}}
133→
134→/* ── Activity Log (collapsible) ──────────────────────── */
135→
136→QFrame#activity_frame {{
137→    background-color: transparent;
138→    padding: 0px {SPACE_SM}px;
139→}}
140→
141→QPushButton#activity_toggle {{
142→    background-color: transparent;
143→    color: {SLATE};
144→    border: none;
145→    font-family: {MONO_FAMILY};
146→    font-size: {SIZE_LABEL}px;
147→    letter-spacing: 2px;
148→    padding: {SPACE_XS}px 0px;
149→    text-align: left;
150→}}
151→
152→QPushButton#activity_toggle:hover {{
153→    color: {SILVER};
154→}}
155→
156→QTextEdit#activity_log {{
157→    background-color: {VOID};
158→    color: {SILVER};
159→    border: 1px solid {GRAPHITE};
160→    border-radius: 4px;
161→    font-family: {MONO_FAMILY};
162→    font-size: {SIZE_SMALL}px;
163→    padding: {SPACE_SM}px;
164→    max-height: 150px;
165→    selection-background-color: rgba(0, 212, 255, 0.3);
166→    selection-color: {WHITE};
167→}}
168→
169→QScrollBar:vertical {{
170→    background-color: {VOID};
171→    width: 6px;
172→    margin: 0px;
173→}}
174→
175→QScrollBar::handle:vertical {{
176→    background-color: {GRAPHITE};
177→    border-radius: 3px;
178→    min-height: 20px;
179→}}
180→
181→QScrollBar::handle:vertical:hover {{
182→    background-color: {SLATE};
183→}}
184→
185→QScrollBar::add-line:vertical,
186→QScrollBar::sub-line:vertical {{
187→    height: 0px;
188→}}
189→
190→QScrollBar::add-page:vertical,
191→QScrollBar::sub-page:vertical {{
192→    background-color: transparent;
193→}}
194→
195→/* ── Chat Input & Send (WhatsApp pill) ─────────────── */
196→
197→QPlainTextEdit#chat_input {{
198→    background-color: {CARBON};
199→    color: {BONE};
200→    border: 1px solid {GRAPHITE};
201→    border-radius: 12px;
202→    font-family: {MONO_FAMILY};
203→    font-size: {SIZE_BODY}px;
204→    padding: 8px {SPACE_MD}px;
205→    min-height: 36px;
206→}}
207→
208→QPlainTextEdit#chat_input:focus {{
209→    border-color: {SLATE};
210→}}
211→
212→QPushButton#send_button {{
213→    background-color: {SIGNAL};
214→    color: {VOID};
215→    border: none;
216→    border-radius: 18px;
217→    font-family: {MONO_FAMILY};
218→    font-size: {SIZE_SMALL}px;
219→    font-weight: 600;
220→    padding: 10px 16px;
221→    min-width: 40px;
222→    min-height: 36px;
223→    max-height: 36px;
224→}}
225→
226→QPushButton#send_button:hover {{
227→    background-color: #33DFFF;
228→}}
229→
230→QPushButton#send_button:pressed {{
231→    background-color: #00A8CC;
232→}}
233→
234→QPushButton#send_button:disabled {{
235→    color: {SLATE};
236→    border-color: {GRAPHITE};
237→}}
238→
239→/* ── Stop Button ────────────────────────────────────── */
240→
241→QPushButton#stop_button {{
242→    background-color: transparent;
243→    color: {ERROR};
244→    border: none;
245→    border-radius: 8px;
246→    font-size: 16px;
247→    min-width: 36px;
248→    max-width: 36px;
249→    min-height: 36px;
250→    max-height: 36px;
251→    padding: 0px;
252→}}
253→
254→QPushButton#stop_button:hover {{
255→    background-color: {CARBON};
256→    color: {WHITE};
257→}}
258→
259→QPushButton#stop_button:pressed {{
260→    background-color: {GRAPHITE};
261→    color: {ERROR};
262→}}
263→
264→/* ── Attach Button ──────────────────────────────────── */
265→
266→QPushButton#attach_button {{
267→    background-color: transparent;
268→    color: {SILVER};
269→    border: none;
270→    border-radius: 8px;
271→    font-size: 18px;
272→    min-width: 36px;
273→    max-width: 36px;
274→    min-height: 36px;
275→    max-height: 36px;
276→    padding: 0px;
277→}}
278→
279→QPushButton#attach_button:hover {{
280→    background-color: {CARBON};
281→    color: {WHITE};
282→}}
283→
284→QPushButton#attach_button:pressed {{
285→    background-color: {GRAPHITE};
286→    color: {SIGNAL};
287→}}
288→
289→/* ── Connection Controls (compact footer) ────────────── */
290→
291→QFrame#connection_frame {{
292→    background-color: {CARBON};
293→    border-top: 1px solid {GRAPHITE};
294→    padding: {SPACE_XS}px {SPACE_MD}px;
295→    min-height: 28px;
296→    max-height: 28px;
297→}}
298→
299→QPushButton#connect_button {{
300→    background-color: transparent;
301→    color: {SIGNAL};
302→    border: 1px solid {SIGNAL};
303→    border-radius: 3px;
304→    font-family: {MONO_FAMILY};
305→    font-size: {SIZE_SMALL}px;
306→    padding: 2px {SPACE_SM}px;
307→    min-width: 72px;
308→}}
309→
310→QPushButton#connect_button:hover {{
311→    background-color: rgba(0, 212, 255, 0.1);
312→}}
313→
314→QPushButton#connect_button:pressed {{
315→    background-color: rgba(0, 212, 255, 0.2);
316→}}
317→
318→QLabel#version_label {{
319→    color: {SLATE};
320→    font-family: {MONO_FAMILY};
321→    font-size: {SIZE_LABEL}px;
322→}}
323→
324→QLabel#port_label {{
325→    color: {SLATE};
326→    font-family: {MONO_FAMILY};
327→    font-size: {SIZE_LABEL}px;
328→}}
329→
330→/* ── Tooltip ─────────────────────────────────────────── */
331→
332→QToolTip {{
333→    background-color: {CARBON};
334→    color: {BONE};
335→    border: 1px solid {GRAPHITE};
336→    font-family: {SANS_FAMILY};
337→    font-size: {SIZE_SMALL}px;
338→    padding: {SPACE_XS}px {SPACE_SM}px;
339→}}
340→"""
341→
342→
343→# ── Status-specific styles ──────────────────────────────
344→
345→STATUS_STYLES = {}
346→for state_name, state_info in STATES.items():
347→    STATUS_STYLES[state_name] = f"""
348→        QLabel#status_dot {{ color: {state_info['color']}; }}
349→        QLabel#status_label {{ color: {state_info['color']}; }}
350→    """
351→
352→
353→# ── Convenience: animation keyframes as color tuples ────
354→
355→STATUS_COLORS = {name: info["color"] for name, info in STATES.items()}
356→
357→
358→if __name__ == "__main__":
359→    print("=" * 50)
360→    print("  SYNAPSE QSS STYLESHEET")
361→    print("=" * 50)
362→    qss = generate_stylesheet()
363→    print(f"\nStylesheet length: {len(qss)} characters")
364→    print(f"Status styles: {list(STATUS_STYLES.keys())}")
365→    print("\n--- Preview (first 500 chars) ---")
366→    print(qss[:500])
367→    print("...")
368→
